import{enhance}from"/assets/select.96281e97aa83.js";import{logTime,when,zone}from"/assets/when.2f5fea25ce95.js";import{PATHS}from"/assets/icons.c1eb39291c5e.js";export function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.textContent=text;return e}const ICON={search:'<path d="M11 4.7a6.3 6.3 0 1 0 0 12.6 6.3 6.3 0 0 0 0-12.6Zm4.8 11.1 3.9 3.9"/>',up:'<path d="m7 14.5 5-5 5 5"/>',down:'<path d="m7 9.5 5 5 5-5"/>',wrap:'<path d="M4 6.5h16M4 12h13a3 3 0 0 1 0 6h-4.5M14.5 15.5 12 18l2.5 2.5M4 17.5h5"/>',follow:'<path d="m7 6.5 5 5 5-5M7 12.5l5 5 5-5"/>',copy:PATHS.copy,save:'<path d="M12 4.5v10M7.5 10l4.5 4.5 4.5-4.5M5 15.5v3a1.5 1.5 0 0 0 1.5 1.5h11a1.5 1.5 0 0 0 1.5-1.5v-3"/>',caret:'<path d="m9.5 7 5 5-5 5"/>',older:'<path d="m11.5 7-5 5 5 5M18 7l-5 5 5 5"/>',newest:'<path d="m6 7 5 5-5 5M12.5 7l5 5-5 5"/>',pause:'<path d="M9 6.5v11M15 6.5v11"/>',play:'<path d="M8.5 6.2v11.6L18 12z"/>',zoomout:'<circle cx="10.5" cy="10.5" r="6"/><path d="m15 15 4.5 4.5M7.8 10.5h5.4"/>',stream:'<path d="M19.5 12a7.5 7.5 0 0 1-12.9 5.2M4.5 12a7.5 7.5 0 0 1 12.9-5.2"/><path d="M17.5 3.8V7h-3.2M6.5 20.2V17h3.2"/>'};export function icon(name){const NS="http://www.w3.org/2000/svg";const svg=document.createElementNS(NS,"svg");svg.setAttribute("viewBox","0 0 24 24");svg.setAttribute("aria-hidden","true");svg.innerHTML=ICON[name];return svg}export function button(cls,label,name,text){const b=el("button",cls);b.type="button";b.title=label;b.setAttribute("aria-label",label);if(name)b.appendChild(icon(name));if(text)b.appendChild(el("span",null,text));return b}const pad=(x,k=2)=>String(x).padStart(k,"0");export const clock=t=>`${when(new Date(t),{month:"short",day:"2-digit"})} ${logTime(t)}`;export const stamp=t=>when(new Date(t),{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});export function zoneName(){try{const part=new Intl.DateTimeFormat("en-US",{timeZone:zone(),timeZoneName:"short"}).formatToParts(new Date).find((x=>x.type==="timeZoneName"));return part?part.value:"UTC"}catch(_){return"UTC"}}export function since(t,t0){let ms=Math.max(0,t-t0);const h=Math.floor(ms/36e5);ms-=h*36e5;const m=Math.floor(ms/6e4);ms-=m*6e4;return`+${h?`${h}:${pad(m)}`:m}:${(ms/1e3).toFixed(3).padStart(6,"0")}`}export function dropdown(label,options,value,onChange){const s=el("select");s.setAttribute("aria-label",label);for(const[v,t]of options){const o=el("option",null,t);o.value=String(v);s.appendChild(o)}s.value=String(value);s.addEventListener("change",(()=>onChange(s.value)));const box=el("span","lv-dd");box.appendChild(s);const drawn=enhance(s,{size:"sm"});return{box:box,sel:s,refresh:()=>{if(drawn&&drawn.refresh)drawn.refresh()}}}